insert into guides (id, content) values ('e36-oil-change', '{"id": "e36-oil-change", "title": "Engine oil & filter change", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Any M50/M52/S50/S52 six (E36 325i/328i, E39 528i, Z3 2.8 & M) — same cartridge filter and drain plug; only the capacity differs", "category": "Engine", "kind": "repair", "heroId": "e36-oil-hero", "glance": {"timeFirst": "30–45 min", "timeRepeat": "20 min", "difficulty": 1, "cost": "$40–90", "risk": "Hot oil · soft aluminum sump threads", "why": "It''s the cheapest, highest-return thing you can do for an S52. This is a naturally aspirated, VANOS engine that BMW itself says uses a little oil — clean oil on schedule is what keeps the VANOS, the chains and the bearings happy. Two slightly special sockets and twenty minutes.", "note": "Every source agrees on the procedure. The only real argument is which viscosity, and that''s laid out below."}, "heroCap": "The filter is a paper cartridge inside a canister on the front of the engine — a 36 mm cap lifts off the top of it. The sump drain plug is directly underneath. No spin-on filter on this engine.", "lifespan": {"title": "When to do it", "headline": ["BMW''s dashboard indicator asks for it on a mileage-and-condition basis; owners change it every 5,000–7,500 miles"], "earliest": "Every 3,000–5,000 miles, or per event, on a tracked car", "detail": "The E36 M3 lights an OILSERVICE (or INSPECTION) lamp under the speedometer as the interval approaches, then a red lamp when it''s overdue. The S52 is a known oil user by design, so the level matters as much as the interval — this car has a dipstick, use it. Short-trip and hard-driven cars want the shorter end of the range.", "factors": ["Track or spirited use", "High mileage", "Unknown service history", "A car that''s using oil between changes"], "inspect": ["Check the level every other fill-up — the S52 uses oil, and running it low is how these engines get hurt"], "confidence": {"level": "community", "n": 4, "note": "Owner practice and BMW''s own service indicator; no fixed factory mileage, it''s condition-based."}}, "should": {"yesIf": ["OILSERVICE or INSPECTION lamp lit under the speedometer", "5,000–7,500 miles since the last change, or you don''t know", "You just bought the car (do it first, before anything else)", "Before or after a track day"], "codes": [], "notes": ["There''s a myth that these have no dipstick. The E36 M3 does — check the level warm, engine off a few minutes, on level ground. The oil-service lamp is a timer, not a level gauge.", "The S52 consumes some oil on purpose. BMW''s own M-engine service bulletin says to check and top up at every fill; a quart every 1,000–1,500 miles is within BMW''s stated tolerance. Keep a spare quart in the trunk and match the viscosity you filled with."], "confidence": {"level": "high", "n": 4, "note": "Procedure and the oil-consumption note agree across Pelican, BIMMERtips, forum practice and a BMW TSB."}}, "parts": [{"tier": "oe", "name": "Oil filter kit, Genuine BMW", "pn": "11427833769", "note": "Cartridge + cap O-ring + drain-plug crush washer in one box", "price": "$18–25", "links": []}, {"tier": "oem", "name": "Oil filter kit, Mahle or Mann", "pn": "Mahle OX 187D · Mann HU 925/4 x", "note": "Same cartridge and seals, maker''s box", "price": "$7–12", "links": []}, {"tier": "oe", "name": "Aluminum drain-plug crush washer", "pn": "in the kit", "note": "New one every change or it weeps", "price": "$1", "links": []}, {"tier": "oe", "name": "Engine oil, buy 7 quarts", "pn": "see ''Which oil'' below", "note": "Fill is ~6.3 qt / 6.0 L; the extra quart is for topping up between changes", "price": "$40–70", "links": []}], "aftermarket": [{"name": "Magnetic drain plug", "note": "Replaces the factory plug (already magnetic on this engine) with a stronger magnet, or adds one if yours has been swapped for a plain plug. Cheap insurance on a 25-year-old engine; read what it catches at each change.", "price": "$10–20", "signal": "Nice-to-have", "links": []}], "tools": [{"name": "17 mm socket for the drain plug", "note": "6-point; a few plugs are 19 mm — look before you buy", "price": "$5"}, {"name": "36 mm socket, or the BMW/Hazet filter-cap cup tool", "note": "The cartridge cap is 36 mm; a deep socket works", "price": "$10–20"}, {"name": "Torque wrench that reads 25 Nm", "price": "$40–80"}, {"name": "Drain pan ≥ 8 quarts, funnel, nitrile gloves, rags", "price": "$20"}, {"name": "Jack + two stands, or ramps", "note": "Only the front needs to come up", "price": "$80–150"}], "before": ["Warm the engine ~10 minutes so the oil carries its dirt out, then let it sit a few minutes so it''s warm, not scalding.", "Level ground; front on ramps or stands. The rear stays down.", "Crack the filter cap on top first (a couple of turns, don''t remove it). It vents the system so the oil drains cleanly, and it confirms you actually have the right socket before you''re committed."], "steps": [{"n": 1, "title": "Warm it, then lift the front", "blocks": [{"t": "text", "b": "Run it to temp, shut it off, and raise the front onto ramps or stands. Pull the engine belly pan if your car has one (a few plastic fasteners) so you can reach the sump plug."}]}, {"n": 2, "title": "Vent the filter cap", "blocks": [{"t": "text", "b": "On top of the engine, the tall black canister near the front: loosen its 36 mm cap two turns and stop. Letting air in here drains the sump more completely and tells you the socket fits before you''re committed."}, {"t": "ill", "id": "e36-oil-hero", "cap": "Cartridge canister on top, sump plug underneath. Vent the cap first, drain second."}]}, {"n": 3, "title": "Drain plug out", "blocks": [{"t": "text", "b": "Pan under the sump. 17 mm on the drain plug (a few cars use 19 mm). Break it loose, then spin it out by hand while pushing up toward the pan so oil doesn''t run down your arm. Let it drain fully."}, {"t": "text", "b": "The plug is magnetic. Wipe it and look at what it caught: fine grey fuzz is normal, glitter or flakes is a reason to keep the old oil in a jug and look closer."}, {"t": "warn", "b": "The oil is hot enough to scald even after it''s ''warm''. Gloves, and keep your forearm out from under the stream."}]}, {"n": 4, "title": "New washer, plug back in", "blocks": [{"t": "text", "b": "Fresh aluminum crush washer on the plug — never reuse the old one. Thread it in by hand, then torque."}, {"t": "torque", "label": "Sump drain plug (M18×1.5)", "nm": 25, "c": {"level": "high", "n": 3, "note": "25 Nm / 18 lb-ft across the Bentley manual, Pelican and multiple E36 references. The 60 Nm figure you''ll see is for the older 19 mm E30-style plug, not this one."}}, {"t": "warn", "b": "These threads are in a soft aluminum pan. 25 Nm is barely more than firm by hand. Over-tighten it and you''re repairing a stripped sump, which means dropping the pan."}]}, {"n": 5, "title": "Cartridge and cap", "blocks": [{"t": "text", "b": "Up top, spin the 36 mm cap off and lift it out; the old cartridge usually comes up with it. Pull the filter off the cap, peel the old O-ring out of the cap''s groove, and wipe the cap clean."}, {"t": "text", "b": "New O-ring in the groove (a smear of fresh oil on it helps it seat), new cartridge onto the cap''s spigot, and lower the assembly back in. Thread the cap down by hand first so you know it isn''t cross-threaded, then torque."}, {"t": "ill", "id": "e36-oil-filter", "cap": "New O-ring in the cap groove, new cartridge on the spigot. Hand-start the cap before the wrench."}, {"t": "torque", "label": "Filter housing cap (36 mm)", "nm": 25, "c": {"level": "varies", "n": 2, "note": "25 Nm is the common value; one long-standing DIY quotes 25 lb-ft (≈34 Nm). It''s a plastic cap into an aluminum housing — 25 Nm and don''t overdo it."}}]}, {"n": 6, "title": "Fill and check", "blocks": [{"t": "text", "b": "Filler cap off the valve cover. Funnel in about 6 quarts to start (fill is ~6.3 qt / 6.0 L). Wait a minute for it to settle into the pan, then read the dipstick and bring it up to — not over — the top mark."}, {"t": "note", "b": "Overfilling an S52 isn''t harmless: too much oil foams and can push past seals. Sneak up on the top mark rather than dumping the whole jug in."}]}, {"n": 7, "title": "Start, look, re-check", "blocks": [{"t": "text", "b": "Start it. The oil-pressure light should go out within a second or two. Let it idle a minute, then look under the car at the drain plug and up at the filter cap for weeping. Shut it off, wait a few minutes, and re-check the dipstick; top up if the filter soaked up its share."}]}, {"n": 8, "title": "Reset the service lamp", "blocks": [{"t": "text", "b": "Optional but satisfying: reset the OILSERVICE indicator. On the E36 you can do it through the diagnostic port with a jumper/paperclip method, or with any cheap OBD service-reset tool. Otherwise the lamp just stays on as a reminder — it does no harm."}]}], "alsoReplace": [{"name": "Air filter", "why": "The other five-minute maintenance item, and the airbox is right there. See the air filter guide."}, {"name": "Valve cover gasket", "why": "If you found oil pooled in the spark-plug wells or weeping down the intake side, the cover gasket is the usual cause and it''s a cheap fix while you''re in the mood."}], "check": {"tab": "Which oil?", "title": "Which viscosity does your S52 want?", "illId": "e36-oil-hero", "illCap": "The S52 is a robust M50-family six, not the high-strung S54. It does not need — and doesn''t love — the S54''s 10W-60.", "rows": [{"see": "Daily street car, moderate climate", "means": "You want easy cold starts and BMW''s own later recommendation for this engine.", "do": "5W-30 or 0W-40 full synthetic (Mobil 1 0W-40 is the forum default and cheap)."}, {"see": "Hot climate or spirited weekend driving", "means": "A little more film strength at temperature without going heavy.", "do": "5W-40 or 10W-40 synthetic."}, {"see": "Track days, or a car that''s using oil", "means": "Peak film strength when it''s hot, and a heavier oil often cuts consumption.", "do": "15W-50 (Mobil 1 or Red Line). It''s the old severe-service answer for the S52."}, {"see": "Someone told you to run 10W-60", "means": "That''s the S54 (E46 M3) requirement, not this engine.", "do": "Skip it. On an S52 it''s overkill and can make a cold engine consume more."}], "c": {"level": "community", "n": 5, "note": "Consensus across mforum, R3VLimited, BobIsTheOilGuy and BimmerWorld; BMW''s published recommendation for the S52 shifted to 5W-30 over the car''s life. Personal use decides the exact grade."}}, "aftercare": ["Reset the service lamp, or note the mileage where you''ll see it.", "Write the date, mileage and viscosity somewhere (tape on the strut tower, or a note).", "Re-check the level after a drive or two — the S52 uses oil, so learn its appetite and keep a matching quart aboard."], "disagreements": [{"topic": "Which viscosity?", "pos": "The 1990s manual era ran 20W-50; BMW later recommended 5W-30 for the S52; the forums split between 5W-30/5W-40 for the street and 15W-50 for hard use.", "call": "5W-30 or 5W-40 synthetic for a street car, 15W-50 if you track it or it drinks oil. 10W-60 is the S54''s oil, not this one."}, {"topic": "Drain plug torque", "pos": "25 Nm (this M18 plug) vs 60 Nm you''ll see quoted.", "call": "25 Nm. The 60 Nm figure is the older 19 mm plug; know which one you have."}, {"topic": "Filter cap torque", "pos": "25 Nm vs 25 lb-ft (≈34 Nm).", "call": "25 Nm. Plastic cap in aluminum — snug, not gorilla."}, {"topic": "How much oil?", "pos": "Manual says 6.3 qt / 6.0 L; some guides pour 6.5.", "call": "Buy 7, fill 6, and let the dipstick set the last bit."}], "sources": ["Pelican Parts E30/E36 Oil Change DIY", "BIMMERtips ''BMW E36 M3 Oil Change Information''", "Bimmerdiy E36 oil change write-up", "Doug''s Domain BMW oil filter service", "Department 69 E36 torque chart (Bentley/TIS-sourced)", "BimmerWorld BMW engine oil guide", "Forum viscosity threads: mforum, R3VLimited, BobIsTheOilGuy, Bimmerfest", "BMW M-engine oil-consumption TSB"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-air-filter', '{"id": "e36-air-filter", "title": "Engine air filter", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Same panel filter across the family: E36 323i/325i/328i · E39 528i · Z3 2.8 & M (S52/M54)", "category": "Engine", "kind": "repair", "heroId": "e36-airbox", "glance": {"timeFirst": "15 min", "timeRepeat": "10 min", "difficulty": 1, "cost": "$12–25", "risk": "None worth mentioning", "why": "The easiest maintenance on the car, and the first thing to check on one you just bought — previous owners forget this for years. A restricted filter costs you nothing dramatic, but a mouse nest or a filter packed with leaves is worth finding before it feeds the engine.", "note": "One panel filter, a few clips. The only variable is whether your airbox lid is held by spring clips or screws."}, "heroCap": "The airbox is the big black box on the driver''s side of the bay. The lid lifts off and the panel filter sits in the base. The air-mass meter (HFM) lives downstream in the intake boot — you don''t touch it for a filter change.", "lifespan": {"title": "When to do it", "headline": ["Inspect yearly; owners replace around every 20,000–30,000 miles"], "earliest": null, "detail": "A paper filter fails gradually. Hold it to the light: if the pleats don''t pass light, or there''s grit and leaves in the box, change it. Cars that sit outdoors collect rodent nests in the airbox — check the intake snorkel too.", "factors": ["Dusty or gravel roads", "Unknown history", "Rodents in the engine bay (check the snorkel)"], "inspect": ["Every oil change: pop the lid and look. It''s a couple of clips."], "confidence": {"level": "community", "n": 3, "note": "Owner practice; no strict factory interval published for this filter."}}, "should": {"yesIf": ["You don''t know when it was last done", "Filter looks grey, or you can''t see light through it", "Debris or nesting in the box", "Every year or so regardless"], "codes": [], "notes": ["Stock paper vs an oiled cotton drop-in: on a stock S52 the paper element isn''t a restriction, and an over-oiled cotton filter can foul the HFM''s hot-film element and throw fuel-trim faults. Stay paper unless you''re going to a full intake (a separate guide)."], "confidence": {"level": "high", "n": 3, "note": "OEM-supplier fitment and forum consensus agree."}}, "parts": [{"tier": "oe", "name": "Air filter, Genuine BMW", "pn": "13721730449", "note": "Panel filter for the factory airbox", "price": "$18–25", "links": []}, {"tier": "oem", "name": "Air filter, Mann or Mahle", "pn": "Mann C 33 189 · Mahle LX 483", "note": "Same filter, maker''s box", "price": "$12–18", "links": []}], "aftermarket": [{"name": "Drop-in cotton panel (K&N, aFe, Turner dry)", "note": "Fits the stock box. Slight airflow gain on paper, real risk of oil on the HFM if over-oiled, and no cold-air benefit. Turner sells a dry version that sidesteps the oiling worry.", "price": "$40–70", "signal": "Community verdict: fine dry, stay paper if unsure", "links": []}], "tools": [{"name": "Flat screwdriver for the lid clips", "note": "or a Phillips/Torx if your box uses screws — check yours"}, {"name": "Shop vac or rag for the box"}], "before": ["Engine off and cool enough to lean over.", "Have the new filter out so you can compare it to the old one and get the orientation right."], "steps": [{"n": 1, "title": "Find and open the box", "blocks": [{"t": "text", "b": "Driver''s side of the engine bay, the large black airbox. Release the lid: most cars use metal spring clips around the edge that you flick open with a flat screwdriver; some have Phillips or Torx screws instead. Free the intake snorkel or any clip holding the lid down."}, {"t": "ill", "id": "e36-airbox", "cap": "Spring clips (or screws) around the lid, panel filter in the base, HFM downstream in the boot. That''s the whole job."}]}, {"n": 2, "title": "Lift the lid, filter out", "blocks": [{"t": "text", "b": "Lift the lid enough to reach in — you usually don''t have to remove it fully or disturb the HFM boot. Lift the panel filter straight out and look at it (table below)."}]}, {"n": 3, "title": "Clean the box", "blocks": [{"t": "text", "b": "Vacuum or wipe the base; leaves and grit collect on the intake side. Check the snorkel for debris or nesting."}]}, {"n": 4, "title": "New filter, close up", "blocks": [{"t": "text", "b": "New filter seated with its rubber edge in the groove, same way round as the old one. Lid back on, clips snapped (or screws snug — it''s plastic, don''t crank), snorkel reconnected. Start it and listen for an intake hiss that means the lid isn''t seated."}]}], "alsoReplace": [{"name": "Cabin microfilter", "why": "Same ''nobody ever changed it'' energy, under the cowl on the passenger side. Ten minutes."}, {"name": "Engine oil", "why": "If you''re doing the yearly once-over anyway, the oil-change guide is the companion job."}], "check": {"tab": "Read the filter", "title": "Reading your old filter", "illId": "e36-airbox", "illCap": "Light through the pleats is the test.", "rows": [{"see": "Off-white, light passes through easily", "means": "Fine.", "do": "Put it back, or replace if it''s cheap and you''re already here."}, {"see": "Grey, light passes with effort", "means": "Doing its job; near the end.", "do": "Replace."}, {"see": "Black, blocked, or debris/nesting in the box", "means": "Restricting airflow; the previous owner never did this.", "do": "Replace, vacuum the box, check the snorkel."}], "c": {"level": "community", "n": 3, "note": "Standard practice; consistent across sources."}}, "aftercare": ["Note the mileage.", "If you switch to an oiled filter and later see residue on the HFM, clean it with MAF cleaner and go back to paper."], "disagreements": [{"topic": "Clips or screws?", "pos": "Airboxes across the E36 run vary between spring clips and screwed lids.", "call": "Look before you buy a tool; both are simple."}, {"topic": "Paper or oiled cotton?", "pos": "Cotton flows a hair more; oiled media can foul the HFM.", "call": "Paper, or a dry cotton panel. Skip pre-oiled unless you''ll maintain it carefully."}], "sources": ["Turner Motorsport E36 M3 air filter fitment", "ECS Tuning E36 M3 air filter / airbox listings", "BimmerBum OEM Mann filter fitment (S50/S52)", "Forum consensus on paper vs oiled and HFM fouling"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-plugs-coils', '{"id": "e36-plugs-coils", "title": "Spark plugs & ignition coils", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Same six pencil coils and OE plug family across M52/S52/M54: E36 328i, E39 528i, Z3 2.8 & M", "category": "Engine", "kind": "repair", "heroId": "e36-ignition", "variants": {"question": "Stock or supercharged?", "hint": "A supercharged S52 runs more cylinder pressure and wants a colder plug with a slightly smaller gap.", "options": [{"id": "stock", "label": "Stock / naturally aspirated", "when": "OE heat range, factory gap", "oeOnly": true}, {"id": "boosted", "label": "Supercharged", "when": "One heat range colder, gapped down"}]}, "glance": {"timeFirst": "45 min", "timeRepeat": "20 min", "difficulty": 1.5, "cost": "$50–90 plugs · $120–260 coils", "risk": "Cross-threading a plug in aluminum · dropping debris in the plug well", "why": "Six plugs, six pencil coils, one per cylinder. A tired plug or a dying coil shows up first as a misfire under load and a rough idle. It''s a 45-minute job with the right socket, and the coils just pull straight up — no bolts holding each one.", "note": "Every source agrees on the procedure. The arguments are plug brand, heat range and gap, so those are below."}, "heroCap": "Under the plastic cover, six pencil coils sit in the plug wells, one per cylinder, with a ground strap linking them. Unplug, lift each coil straight up, and the plug is directly below on a thin-wall 14 mm socket.", "lifespan": {"title": "When to expect it", "headline": [{"text": "Plugs: every 30,000–45,000 miles on a stock car", "only": ["stock"]}, {"text": "Plugs: every 15,000–25,000 miles on a supercharged car; check the gap more often", "only": ["boosted"]}], "earliest": "Sooner on a car that''s been sitting, or one that fouls plugs from oil consumption", "detail": "A worn plug misfires under load first — a stumble at full throttle that clears at part throttle. A dying coil is the same on one cylinder, usually with a cylinder-specific misfire code. Coils on these cars are a known wear item; swap a suspect coil to a neighbouring cylinder and see if the misfire follows it.", "factors": ["Supercharger or aggressive tune", "Oil in the plug wells from a leaking valve-cover gasket (kills coils)", "Wrong gap for the boost level", "A car that''s been sitting"], "inspect": ["Any misfire code: move the coil to another cylinder. If the miss follows the coil, it''s the coil."], "confidence": {"level": "community", "n": 4, "note": "Owner practice and vendor kit notes; exact factory interval varies by source."}}, "should": {"yesIf": ["Misfire under load, worse cold and damp", "Cylinder-specific misfire code (P0301–P0306)", "30k+ since the last plugs, or unknown", "Just supercharged it and still on stock plugs"], "codes": ["P0300", "P0301", "P0302", "P0303", "P0304", "P0305", "P0306"], "notes": ["Plug, decoded: the OE plug is an NGK platinum (BKR6EQUP family) or the Bosch equivalent — heat range 6, gapped around 0.032\" (0.8 mm) from the box. ''Colder'' (a 7) sheds heat faster and is for boosted cars; it does not add power on a stock engine.", {"text": "Gap: leave the pre-gapped OE plug alone. If you check it, ~0.032\" (0.8 mm) is the target. Don''t lever on a platinum tip to adjust it — check with a wire gauge only.", "only": ["stock"]}, {"text": "Gap: close it toward 0.024–0.028\" so the spark doesn''t blow out under boost. Too wide is your full-throttle misfire; your supercharger vendor usually publishes a number — follow it.", "only": ["boosted"]}, "Coils: the OE pencil coil (Bosch/Bremi) is the reliable part. The cheap ''red'' coils sold online claim power gains they don''t make — buy them for looks if you like, not for performance."], "confidence": {"level": "high", "n": 4, "note": "Plug family, gap and coil guidance agree across ECS, Turner, BimmerWorld and forum threads."}}, "parts": [{"tier": "oe", "name": "Spark plugs (×6), NGK platinum", "pn": "NGK BKR6EQUP · BMW 12120037607", "note": "OE heat range, pre-gapped ~0.032\"", "price": "$50–70", "links": [], "only": ["stock"]}, {"tier": "oe", "name": "Spark plugs (×6), Bosch OE", "pn": "Bosch FR7LDC+ (supersedes F7LDCR)", "note": "The other OE-supplier plug", "price": "$40–60", "links": [], "only": ["stock"]}, {"tier": "aftermarket", "name": "Spark plugs (×6), one heat range colder", "pn": "colder NGK (a ''7'' plug); confirm with your kit", "note": "Gap down to 0.024–0.028\" for boost", "price": "$40–70", "links": [], "only": ["boosted"]}, {"tier": "oe", "name": "Ignition coils (×6), Bosch or Bremi", "pn": "BMW 12131748017", "note": "Pencil/stick coils; replace as a set if they''re original", "price": "$120–260", "links": []}, {"tier": "oe", "name": "Coil boots (×6, if using Bremi coils)", "pn": "12131730412", "note": "Only some coils use separate boots — check yours", "price": "$30–60", "links": []}, {"tier": "oe", "name": "Anti-seize, dielectric grease", "pn": "—", "note": "A trace on the plug threads and inside each coil boot", "price": "$10", "links": []}], "aftermarket": [{"name": "Dinan ''blue'' performance coils", "note": "OE-quality pencil coils in blue with a modest spark claim; the tidy upgrade if you want new coils and the look. Real gain is small.", "price": "$180–260 / set", "signal": "Nice set, mild claim", "links": []}, {"name": "''Red'' online coils", "note": "Cheap, sold with big power claims. They fire; they don''t add the horsepower the listings promise. Fine as budget replacements, buy with eyes open.", "price": "$50–90 / set", "signal": "Budget, ignore the claims", "links": []}], "tools": [{"name": "Thin-wall 14 mm spark-plug socket with rubber insert, extension, 3/8\" ratchet"}, {"name": "5 mm hex for the coil ground-strap bolts"}, {"name": "Torque wrench to 30 Nm"}, {"name": "Wire-type gap gauge (not a coin disc)"}, {"name": "Compressed air or a vacuum for the plug wells; small flat screwdriver for the connector locks"}], "before": ["Engine cold. Plug threads pull out of hot aluminum far too easily.", "Blow or vacuum the plug wells before the plugs come out so nothing drops into a cylinder.", "Do one cylinder at a time so nothing gets mixed up."], "steps": [{"n": 1, "title": "Cover off, unplug the coils", "blocks": [{"t": "text", "b": "Pull the plastic engine cover (a couple of trim nuts or it lifts off its ball studs). Six pencil coils in a row along the head. Lift the ground strap off if fitted, then unclip each coil''s connector — a small screwdriver releases the wire lock."}]}, {"n": 2, "title": "Pull the coils", "blocks": [{"t": "text", "b": "Grip each coil by its body and pull straight up; they''re a friction fit and can be stubborn after years. Twist gently as you pull. Look at each boot for cracks or oil — oil in the well means the valve-cover gasket is leaking and cooking the coils."}, {"t": "ill", "id": "e36-ignition", "cap": "No bolts hold each coil. Unplug, pull straight up, the plug is directly below."}]}, {"n": 3, "title": "Plugs out", "blocks": [{"t": "text", "b": "Blow the wells clear. 14 mm plug socket on an extension, break each plug loose and spin it out. Read them as they come out (table below) — colour tells you a lot."}]}, {"n": 4, "title": "Gap and fit the new plugs", "caution": true, "blocks": [{"t": "text", "b": "Check the gap with a wire gauge without touching the centre electrode: ~0.032\" (0.8 mm) for a stock car. Leave OE platinum plugs at the factory gap if they measure right.", "only": ["stock"]}, {"t": "text", "b": "Set the gap to your vendor''s number (0.024–0.028\" is typical for a supercharged S52), bending only the ground strap. Don''t lever on the centre electrode.", "only": ["boosted"]}, {"t": "text", "b": "A trace of anti-seize on the threads (a little — too much changes the torque reading). Thread each plug in by hand with the socket, no ratchet, until it seats, then torque. If it resists before seating, back out and restart."}, {"t": "torque", "label": "Spark plugs", "nm": 25, "c": {"level": "varies", "n": 2, "note": "25–30 Nm (18–22 lb-ft) across E36 references for this gasketed plug. Hand-tight plus a firm quarter-turn lands here."}}, {"t": "warn", "b": "Cross-threading a plug into the aluminum head is the one way this job goes badly. Hand-start every plug, every time."}]}, {"n": 5, "title": "Coils in, connectors on", "blocks": [{"t": "text", "b": "A dab of dielectric grease inside each coil boot. Push each coil down until it seats over the plug with a firm stop. Connectors on until they click, ground strap back across the top. Cover on."}]}, {"n": 6, "title": "Start and drive", "blocks": [{"t": "text", "b": "Idle should smooth out immediately. Drive it and give it full throttle in a mid gear once warm; a stumble that''s now gone was the point. A miss that remains with new plugs and coils isn''t ignition — look at the VANOS, a vacuum leak, or fuel."}]}], "alsoReplace": [{"name": "Valve-cover gasket", "why": "Oil in the plug wells kills coils. If the wells were wet, the cover gasket is the cause and it''s a cheap fix while the coils are out. See that guide."}, {"name": "Ground strap / coil bracket bolts", "why": "Cheap, and a loose ground here causes intermittent misfires that look like bad coils."}], "check": {"tab": "Read the plugs", "title": "Reading the old plugs", "illId": "e36-ignition", "illCap": "Tan is right. Everything else is a clue.", "rows": [{"see": "Light tan to grey electrode, no deposits", "means": "Healthy engine, plug simply aged.", "do": "Replace, same type."}, {"see": "Black, sooty and dry", "means": "Rich, too cold a plug, or a lot of idling.", "do": "Check heat range and gap; a colder plug on a stock car will do this."}, {"see": "Oily, wet", "means": "Oil in the well from the cover gasket, or oil past the guides/rings.", "do": "Gasket first; new coil on that cylinder."}, {"see": "White, blistered, beads on the electrode", "means": "Too hot: lean, too much boost, or too hot a plug.", "do": "Colder plug and a look at the tune before you hurt a piston."}], "c": {"level": "community", "n": 3, "note": "Standard plug reading; consistent with forum experience on this engine."}}, "aftercare": ["Note mileage and plug type.", "Misfire returns on one cylinder: swap that coil with a neighbour and see if it moves."], "disagreements": [{"topic": "Gap", "pos": "0.028\" vs 0.032\" quoted across catalogs.", "call": "~0.032\" stock (leave the pre-gapped OE plug alone); gap down for boost."}, {"topic": "Plug torque", "pos": "25 Nm vs 30 Nm (18–22 lb-ft).", "call": "25–30 Nm; hand-tight plus a firm quarter-turn."}, {"topic": "Do red/blue coils add power?", "pos": "Listings claim 15–25 hp.", "call": "No. Buy coils for reliability and looks; the OE pencil coil is the standard."}], "sources": ["ECS Tuning E36 M3 ignition listings (plug supersession, coils, boots)", "Turner Motorsport E36 M3 spark plugs", "BimmerWorld NGK BKR6EQUP / plug listings", "Go-Parts E36 M3 spark plug guide (part numbers, gap, torque)", "mforum plug cross-reference and heat-range threads"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-valve-cover-gasket', '{"id": "e36-valve-cover-gasket", "title": "Valve cover gasket & coil boots", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Same M50/S50-style cover gasket across the family: E36 328i · E39 528i · Z3 2.8 & M (M52/S52)", "category": "Engine", "kind": "repair", "heroId": "e36-valvecover", "glance": {"timeFirst": "1–1.5 hr", "timeRepeat": "45 min", "difficulty": 2, "cost": "$30–60 (gasket kit) · +$40–80 coil boots", "risk": "Dropping debris into the head · over-torquing a soft grommet", "why": "The valve cover gasket is the classic E36 oil leak. When it goes, oil weeps down the block and onto the exhaust — a burning smell and, if it''s bad, a genuine fire risk — and it fills the spark-plug wells, which is what kills coils. It''s a cheap, satisfying afternoon that fixes a leak and protects the ignition system.", "note": "Not hard, but detail-sensitive: new grommets and half-moon seals every time, a light hand on the torque, and nothing dropped into the head."}, "heroCap": "The cover seals three ways: a perimeter gasket, a gasket ring around each spark-plug tube, and two half-moon seals at the front arches. Fifteen rubber grommets/washers sit under the hold-down bolts — those leak more often than the gasket itself.", "lifespan": {"title": "When to expect it", "headline": ["Commonly leaking by 80,000–120,000 miles, or whenever the rubber has gone hard"], "earliest": "Sooner in a hot climate, or on a car that''s sat for years", "detail": "Oil on the intake side of the block, a burning smell after a drive, or wet spark-plug wells when you pull the coils are the tells. A leak bad enough to reach the PCV can let unmetered air in and roughen the idle. The cover itself doesn''t wear — the gasket, grommets and half-moons harden and shrink.", "factors": ["Age and heat", "Oil in the plug wells (found during a plug/coil job)", "A leak you can smell burning off the exhaust"], "inspect": ["Every plug/coil job: look in the wells. Oil there is your cue."], "confidence": {"level": "community", "n": 4, "note": "Owner reports and vendor notes; a very common E36 leak."}}, "should": {"yesIf": ["Oil weeping down the intake or exhaust side of the block", "Burning-oil smell after driving", "Oil pooled in the spark-plug wells", "Rough idle traced to oil-fouled coils or a PCV leak"], "codes": [], "notes": ["Replace the 15 grommets/sealing washers even if you''re only chasing the perimeter leak — they''re the usual culprit and they''re pennies. BMW says replace them every time the cover comes off.", "If you''re in here, do the coils and plugs at the same time (they have to come off anyway) and check the coil boots — dried, cracked boots let spark jump to the head and misfire. See the plugs & coils guide."], "confidence": {"level": "high", "n": 4, "note": "Procedure and the grommet advice agree across Pelican, Red Eye Garage, Doug''s Domain and ECS."}}, "parts": [{"tier": "oe", "name": "Valve cover gasket set", "pn": "BMW 11120034108 (Victor Reinz / Elring)", "note": "Perimeter gasket + spark-plug tube gaskets", "price": "$25–45", "links": []}, {"tier": "oe", "name": "Grommets / sealing washers (×15)", "pn": "often in the set; else BMW 11121437395", "note": "Under each hold-down bolt — replace every time", "price": "$8–20", "links": []}, {"tier": "oe", "name": "Half-moon seals (×2)", "pn": "in most complete kits", "note": "Front cam-arch seals; seated in RTV", "price": "in kit", "links": []}, {"tier": "oe", "name": "RTV sealant", "pn": "Reinzosil / BMW Drei Bond / Ultra-Black", "note": "Only at the half-moons and the corner joints — not the whole perimeter", "price": "$8", "links": []}, {"tier": "oe", "name": "Coil boots (×6), optional", "pn": "12131730412 (Bremi-style)", "note": "If dried or cracked, do them while you''re here", "price": "$40–80", "links": []}], "aftermarket": [{"name": "Complete kit with hardware", "note": "ECS and others sell a set bundling the gaskets, all 15 washers, half-moons and sealant in one box — the easy way to not miss a piece.", "price": "$40–70", "signal": "One-box pick", "links": []}], "tools": [{"name": "10 mm socket / nut driver for the cover bolts and ground nuts", "note": "a flex or swivel helps at the rear"}, {"name": "5 mm hex and a 14 mm plug socket (coils and plugs come off first)"}, {"name": "Torque wrench that reads 10 Nm (inch-pound wrench)", "note": "this is a very low torque"}, {"name": "Plastic scraper, brake cleaner, lint-free rags, RTV"}], "before": ["Engine cold and clean-ish; degrease the top end first so grit doesn''t fall in.", "Anything you drop into an open head is a problem. Rag over the cam area while you clean, and count your rags before the cover goes back on.", "Lay the coils and their connectors out in order as they come off."], "steps": [{"n": 1, "title": "Cover, coils and plugs off", "blocks": [{"t": "text", "b": "Pull the plastic engine cover. Unplug and remove the six pencil coils (ground strap, connectors, pull straight up — see the plugs & coils guide) and, if you''re doing them, the plugs. Move the wiring harness and any ground straps off the cover''s studs and set them aside."}]}, {"n": 2, "title": "Free the cover", "blocks": [{"t": "text", "b": "Unbolt the valve-cover hold-down bolts (10 mm), each with a rubber grommet/washer under it — note where the taller studs and ground points are. Release any breather/PCV hose clipped to the cover. Lift the cover straight up and off; if the gasket has glued it down, break it free gently, don''t pry against the head."}, {"t": "ill", "id": "e36-valvecover", "cap": "Perimeter gasket, plug-tube rings, two front half-moons, and a grommet under every bolt. The grommets are the usual leak."}, {"t": "warn", "b": "With the cover off, the cam area is open. Rag over it. Nothing — no bolt, no grommet, no rag — goes into the head."}]}, {"n": 3, "title": "Clean the sealing surfaces", "blocks": [{"t": "text", "b": "Peel the old gaskets and half-moons out of the cover. Plastic-scrape and brake-clean the cover''s channel and the head''s mating rail until they''re dry and oil-free. Check the cover for warping or cracks while it''s off — a warped cover won''t seal no matter how good the gasket is."}]}, {"n": 4, "title": "New gaskets, half-moons and grommets", "blocks": [{"t": "text", "b": "Seat the new perimeter gasket and the plug-tube gaskets fully in the cover''s grooves. Fit the two half-moon seals at the front arches with a small dab of RTV, and put a little RTV in the corner joints where the perimeter gasket meets the arches — those corners are the classic re-leak spot. Everywhere else stays dry; RTV is not a substitute for the gasket."}, {"t": "note", "b": "Put a fresh grommet/washer on every hold-down bolt before the cover goes on. Reusing hard old ones is the most common reason a fresh gasket still weeps."}]}, {"n": 5, "title": "Cover on, torque light", "caution": true, "blocks": [{"t": "text", "b": "Lower the cover square onto the head so the gasket doesn''t roll out of its groove. Start every bolt by hand. Torque from the centre outward, in stages, to the final value — and stop the moment it''s there."}, {"t": "torque", "label": "Valve cover bolts", "nm": 10, "c": {"level": "high", "n": 3, "note": "10 Nm (89 in-lb) across Pelican, Red Eye Garage and Doug''s Domain. That''s barely more than snug — the grommet squashes and it''s done."}}, {"t": "warn", "b": "This is inch-pounds, not foot-pounds. Over-torque crushes the grommets, distorts the cover and makes it leak worse. Once the bolt bottoms on its grommet, stop."}]}, {"n": 6, "title": "Coils, plugs, hoses back", "blocks": [{"t": "text", "b": "Ground straps and harness back on their studs (nuts barely snug). Plugs and coils back in (dielectric grease in the boots), connectors clicked, breather/PCV hose reconnected, engine cover on."}]}, {"n": 7, "title": "Run it and check", "blocks": [{"t": "text", "b": "Start it, let it warm up, and look along both sides of the block for weeping — especially the front corners and the rear of the cover. A drive and a re-check the next day confirms it. Persistent seepage after all this usually means a warped cover."}]}], "alsoReplace": [{"name": "Spark plugs & coils", "why": "They''re already out. Fresh plugs and a look at the coil boots while you''re here saves pulling it all twice. See that guide."}, {"name": "Oil filter housing gasket", "why": "The other classic top-end leak on these engines, and right next door — worth a look while you''re cleaning oil off the block."}, {"name": "PCV / breather hose", "why": "Brittle with age; a cracked breather causes the same rough-idle unmetered-air symptom people blame on the gasket."}], "check": {"tab": "Where''s it leaking?", "title": "Is it really the valve cover?", "illId": "e36-valvecover", "illCap": "Oil high on the block points at the cover; lower down points elsewhere.", "rows": [{"see": "Oil high on the intake/exhaust side, wet plug wells", "means": "Valve cover gasket and/or the grommets.", "do": "This job. Replace grommets and half-moons, not just the gasket."}, {"see": "Oil around the round housing lower on the intake side", "means": "Oil filter housing gasket, not the cover.", "do": "Different gasket; clean and watch to confirm the source."}, {"see": "Oil at the very back of the head, upper", "means": "Could be the cover''s rear edge or the VANOS seals/gasket.", "do": "Cover gasket first; if it persists, look at the VANOS area."}], "c": {"level": "community", "n": 3, "note": "Standard leak diagnosis on the M52/S52 top end."}}, "aftercare": ["Re-check for weeping after a heat cycle and again in a few days.", "Clean the old oil off the block first so a new spot is obvious.", "If it still leaks, pull the cover and check it on a flat surface for warp."], "disagreements": [{"topic": "Torque value", "pos": "89 in-lb (10 Nm) vs a stray ''9 Nm'' comment.", "call": "10 Nm / 89 in-lb. Either way it''s inch-pounds — snug, not tight."}, {"topic": "RTV everywhere?", "pos": "Some smear sealant around the whole perimeter.", "call": "No. RTV only at the half-moons and the corner joints; the gasket seals the rest."}, {"topic": "Reuse the washers?", "pos": "They look fine, why replace them.", "call": "Replace all 15. Hard old grommets are the top reason a new gasket still leaks."}], "sources": ["Pelican Parts E30/E36 valve cover replacement", "Red Eye Garage E36 M3 valve cover gasket write-up", "Doug''s Domain E36 (M52) valve cover gasket DIY (torque, kit contents)", "ECS Tuning / BimmerWorld E36 M3 valve cover gasket sets (part numbers)", "Turner Motorsport valve cover parts (gasket fitment M50/M52/S50/S52)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-ofh-gasket', '{"id": "e36-ofh-gasket", "title": "Oil filter housing gasket", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Same profile gasket across the six-cylinder family: E36 328i · E39 528i · Z3 2.8 & M · and M50/M54 cars (E46, X3, X5) with the same housing", "category": "Engine", "kind": "repair", "heroId": "e36-ofh", "glance": {"timeFirst": "1.5–2 hr", "timeRepeat": "1 hr", "difficulty": 2.5, "cost": "$15–40 (gasket + VANOS line seals)", "risk": "Accessory belt off · oil spill · deforming the gasket by uneven torque", "why": "After the valve cover, this is the leak BMW''s own shops replace most. A flat ''profile'' gasket sits between the oil filter housing and the block; it hardens and shrinks with age and weeps oil down the intake side. Cheap part, a couple of hours, and the housing comes off behind the accessory belt.", "note": "Best done at an oil change — you''re draining the oil anyway, and the VANOS oil line that comes off with the housing is worth resealing while you''re there."}, "heroCap": "The oil filter housing bolts to the front-left of the block; the profile gasket seals the joint between them. The accessory belt, the belt tensioner and the VANOS oil feed line all live on or around it, so they come off to reach the gasket.", "lifespan": {"title": "When to expect it", "headline": ["Commonly weeping by 100,000+ miles as the gasket hardens"], "earliest": "Sooner in hot climates", "detail": "Oil on the intake side of the block that isn''t coming from the valve cover usually traces to here. Because the housing also carries oil to the VANOS, the line and its seals often weep at the same time. The gasket doesn''t fail suddenly — it shrinks, and the seep gets worse over a season.", "factors": ["Age and heat", "Original gasket never replaced", "A VANOS oil line that''s also weeping"], "inspect": ["When you clean oil off the block: is the source the cover (high) or the housing (mid, front-left)?"], "confidence": {"level": "community", "n": 4, "note": "Turner, eEuroparts and ShiftBMW all call it one of the most common M52/S52 leaks."}}, "should": {"yesIf": ["Oil weeping from the front-left of the block, below the cover", "Oil around the base of the oil filter housing", "You traced a leak past the valve cover to here", "You''re doing an oil change and want to kill a known leak"], "codes": [], "notes": ["Do it with an oil change — the oil has to come out anyway, and refilling with a fresh filter closes the loop.", "The VANOS oil feed line unbolts with the housing. Reseal it (or replace the line) while it''s off; it''s the other common weep right next door and you won''t want to be back in here for it."], "confidence": {"level": "high", "n": 4, "note": "Procedure and the ''do the VANOS line too'' advice agree across ShiftBMW, eEuroparts and Turner."}}, "parts": [{"tier": "oe", "name": "Oil filter housing profile gasket", "pn": "BMW 11421719855 (Elring 816965)", "note": "The gasket between housing and block", "price": "$8–12", "links": []}, {"tier": "oe", "name": "VANOS oil line seals / crush washers", "pn": "per your line", "note": "The feed line comes off with the housing — reseal it", "price": "$5–15", "links": []}, {"tier": "oe", "name": "Oil & filter", "pn": "see the oil-change guide", "note": "You''re draining anyway", "price": "$40–70", "links": []}], "aftermarket": [{"name": "Aluminum-cased VANOS oil line", "note": "If the original line is weeping at the crimp rather than the seals, an upgraded braided/alloy line ends that for good. Optional; reseal first if the line body is sound.", "price": "$40–90", "signal": "Only if the line itself weeps", "links": []}], "tools": [{"name": "Belt tools: the tensioner needs a wrench/socket to swing it off"}, {"name": "Sockets and hex/Torx to suit the housing bolts and VANOS line banjo", "note": "basic set; a stubby or swivel helps in the tight spots"}, {"name": "Torque wrench for the housing bolts", "note": "even, gentle — see the torque note"}, {"name": "Drain pan, brake cleaner, lint-free rags"}], "before": ["Disconnect the battery in the trunk before working around the front of the engine.", "Warm the engine only slightly (a few minutes) to soften the old gasket — don''t work on a fully hot engine.", "Drain the oil first (do this as an oil change) or expect a messy spill when the housing comes off; pockets of oil sit behind it.", "Photograph the accessory-belt routing before it comes off."], "steps": [{"n": 1, "title": "Belt off", "blocks": [{"t": "text", "b": "Swing the belt tensioner to release tension and slip the main accessory belt off; take the A/C belt off too if it''s in the way. Note the routing (or use your photo)."}]}, {"n": 2, "title": "VANOS oil line and anything on the housing", "blocks": [{"t": "text", "b": "Disconnect the VANOS oil feed line at the housing (catch a little oil), and unclip or unbolt anything else mounted to the housing that''s in the way. Keep the banjo/seals together so you know what to reseal."}, {"t": "ill", "id": "e36-ofh", "cap": "Housing bolts to the block over the profile gasket; the VANOS oil line and the belt tensioner live on it. Two dowels locate the housing — don''t lose them."}]}, {"n": 3, "title": "Unbolt and pull the housing", "blocks": [{"t": "text", "b": "Remove the housing bolts, keeping track of lengths and locations. Ease the housing straight off the block — it sits on two locating dowels and will release a pocket of oil. Check that both dowels stayed in place (a missing dowel is a guaranteed re-leak)."}, {"t": "warn", "b": "Oil will run when the housing comes free. Pan underneath, rags ready."}]}, {"n": 4, "title": "Clean and inspect", "blocks": [{"t": "text", "b": "Peel the old profile gasket off. Clean both the housing face and the block face until they''re dry and oil-free, and check both for pitting or a nick that would keep a new gasket from sealing. Confirm both dowels are present and seated."}]}, {"n": 5, "title": "New gasket, no grease", "caution": true, "blocks": [{"t": "text", "b": "Seat the new profile gasket in its groove. A wipe of clean engine oil is fine to hold it; do not use grease — grease lets the gasket slip out of the groove as you tighten, which is the classic ''I replaced it and it still leaks'' cause."}, {"t": "note", "b": "Make sure the gasket stays fully in its channel as you offer the housing up. A pinched or half-seated gasket is the other common re-leak."}]}, {"n": 6, "title": "Housing on, torque even", "caution": true, "blocks": [{"t": "text", "b": "Guide the housing onto its dowels so the gasket doesn''t shift, start all bolts by hand in their right locations, then tighten evenly in a cross pattern so the housing draws down square and the gasket isn''t deformed."}, {"t": "torque", "label": "Oil filter housing bolts", "nm": 22, "c": {"level": "varies", "n": 1, "note": "No single widely-published factory figure turned up this pass; owner guides tighten evenly and snug (roughly 22 Nm for the larger bolts, ~10 Nm for any M6). Even clamp without crushing the gasket matters more than the exact number. Verify against a Bentley manual if you have one."}}, {"t": "warn", "b": "Uneven or over-tight bolts deform the gasket and it leaks. Snug and even, cross pattern."}]}, {"n": 7, "title": "VANOS line, belt, oil", "blocks": [{"t": "text", "b": "Reconnect the VANOS oil line with fresh seals/washers. Refit the belt(s) on the routing you photographed and check the tensioner sets tension. Reconnect the battery. Fill with fresh oil (new filter), start, and check the housing joint and the VANOS line for leaks."}]}, {"n": 8, "title": "Run and re-check", "blocks": [{"t": "text", "b": "Warm it up, look for any weep at the housing base and the VANOS line, then re-check the next day once the block''s been cleaned. A leak that persists means a pinched gasket, a missing dowel, or a warped/pitted face."}]}], "alsoReplace": [{"name": "VANOS oil line & seals", "why": "It''s off. The other common weep here, and you don''t want to pull the belt again for it."}, {"name": "Engine oil & filter", "why": "Drained anyway — the natural pairing. See the oil-change guide."}, {"name": "Accessory belt & tensioner", "why": "The belt''s off and a 25-year-old belt or a tired tensioner is worth doing now. See the belts guide."}], "check": {"tab": "Which leak?", "title": "Is it the housing, or something above it?", "illId": "e36-ofh", "illCap": "Height on the block is the quickest tell.", "rows": [{"see": "Oil high on the block, wet plug wells", "means": "Valve cover gasket, not the housing.", "do": "See the valve cover guide."}, {"see": "Oil mid-height at the front-left, around the housing base", "means": "Oil filter housing profile gasket.", "do": "This job. Reseal the VANOS line while you''re in there."}, {"see": "Oil at the housing but also up a small line", "means": "VANOS oil line seals weeping too.", "do": "Do both together — the line''s off anyway."}], "c": {"level": "community", "n": 3, "note": "Standard M52/S52 leak diagnosis."}}, "aftercare": ["Clean the block first so a fresh weep is obvious.", "Re-check after a heat cycle and the next day.", "Still leaking with correct torque: pull it and look for a pinched gasket, a missing dowel, or a pitted face."], "disagreements": [{"topic": "Grease the gasket?", "pos": "Some lube the seal to help it seat.", "call": "Clean engine oil at most, never grease — grease makes the gasket slip and leak."}, {"topic": "Housing bolt torque", "pos": "No single well-published figure surfaced this pass.", "call": "Even and snug, cross pattern; verify against a Bentley manual. Flagged single-source."}, {"topic": "Just the gasket, or the VANOS line too?", "pos": "You can reseal only the housing.", "call": "Do the VANOS line seals while it''s off — same access, same common weep."}], "sources": ["Turner Motorsport oil filter housing gasket (fitment, ''most common leak'', VANOS line note)", "eEuroparts M50/M52/M54/S52 oil filter housing gasket guide", "ShiftBMW S52 & M52 oil filter housing gasket repair (procedure, do-with-oil-change)", "BimmerWorld / Bevinsee gasket listings (part numbers, fitment)", "Pelican Parts oil filter housing gasket article (grease/slip and dowel notes)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-fuel-filter', '{"id": "e36-fuel-filter", "title": "Fuel filter", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Same filter across the family: E36 323i/328i · E39 528i · Z3 2.8 & M (BMW 13321740985)", "category": "Engine", "kind": "repair", "heroId": "e36-fuelfilter", "glance": {"timeFirst": "45 min", "timeRepeat": "25 min", "difficulty": 2, "cost": "$15–25", "risk": "Fuel spillage · fire · fuel vapor", "why": "A paper element in an aluminum canister under the floor. It''s cheap, it''s the first thing to try for hard starts, sputtering or a lean-running engine, and previous owners forget it for years. Out of sight, out of mind — and overdue on most used M3s.", "note": "The whole job is easy; the only respect it demands is that you''re working under a fuel line. Depressurize first, near-empty tank, extinguisher handy."}, "heroCap": "The filter lives under the car on the driver''s side, roughly beneath the seat, behind a plastic cover. Fuel flows through it in one direction — the arrow on the filter has to point the right way when it goes back.", "lifespan": {"title": "When to do it", "headline": ["Factory interval is every Inspection II — roughly every 30,000–40,000 miles"], "earliest": null, "detail": "A clogging filter starves the engine: hard starts, sputtering, hesitation, lean faults, or a stumble under load as pressure drops. If you don''t know when it was last done, it''s due. The E36''s pump lives in the top of the tank and pumps from the top, so the tank won''t gravity-drain when you open the line — a small mercy.", "factors": ["Unknown history", "A deteriorating tank or bad fuel", "High mileage"], "inspect": ["No real inspection — it''s a mileage/time item. Just do it on schedule."], "confidence": {"level": "community", "n": 4, "note": "Interval and procedure agree across Pelican, Turner, Doug''s Domain and Red Eye Garage."}}, "should": {"yesIf": ["Hard starting, sputtering, or a stumble under load", "Lean-mixture or misfire faults you can''t otherwise explain", "30k+ since the last change, or unknown", "You just bought the car"], "codes": ["P0171", "P0174"], "notes": ["Run the tank low first so a spill is a cupful, not a flood.", "Note the flow-direction arrow on the old filter before it comes off. Fitting the new one backwards is the one way to get this wrong."], "confidence": {"level": "high", "n": 4, "note": "Standard maintenance item; consistent across sources."}}, "parts": [{"tier": "oe", "name": "Fuel filter", "pn": "BMW 13321740985 (Mann / Mahle / Hengst / Meyle)", "note": "Paper element in an aluminum canister", "price": "$15–25", "links": []}, {"tier": "oe", "name": "Hose clamps (if yours are worm-gear)", "pn": "—", "note": "Some cars have spring clamps you can reuse; replace tired worm clamps", "price": "$3", "links": []}], "aftermarket": [], "tools": [{"name": "Jack + stand for the driver''s side; wheel chocks"}, {"name": "Flat screwdriver / small socket for the cover and hose clamps"}, {"name": "Fuel-line pliers or a hose clamp to pinch the line; catch pan, rags"}, {"name": "Safety glasses, gloves, fire extinguisher within reach"}], "before": ["Run the tank as low as you safely can before you start.", "Pull the fuel-pump fuse (fuse #18 on the E36 — verify against the diagram on your fuse-box lid, it''s easy to grab the wrong one) and crank the engine a couple of times to bleed off pressure.", "Disconnect the battery in the trunk. Extinguisher and safety glasses ready — you''ll be under a dripping line looking up."], "steps": [{"n": 1, "title": "Depressurize", "blocks": [{"t": "text", "b": "Fuse #18 out, crank twice so the engine tries to start and dies. That drops most of the rail pressure. Battery negative off."}]}, {"n": 2, "title": "Lift the driver''s side, cover off", "blocks": [{"t": "text", "b": "Chock the wheels, jack the driver''s side and set a stand. Under the floor, roughly below the seat, a plastic protective cover holds the filter — remove its four bolts/screws and set it aside. The grey canister is the filter."}, {"t": "ill", "id": "e36-fuelfilter", "cap": "Under the floor, driver''s side. Cover off (4 fasteners), filter in its bracket, flow arrow pointing toward the engine."}]}, {"n": 3, "title": "Disconnect the lines", "caution": true, "blocks": [{"t": "text", "b": "Loosen the clamp on one hose and ease it off — fuel will run, so have the pan and rags ready and your face out of the stream. Pinch or plug the tank-side line to slow the drip. Free the other hose and the filter''s bracket clamp."}, {"t": "warn", "b": "Fuel and fuel vapor. No sparks, no smoke, ventilation, extinguisher in reach. Wipe every drip."}]}, {"n": 4, "title": "Swap, minding the arrow", "blocks": [{"t": "text", "b": "Note the flow-direction arrow on the old filter, then fit the new one the same way — arrow pointing in the direction of fuel flow (toward the engine). Seat it in the bracket, hoses on, clamps snug."}, {"t": "note", "b": "Backwards is the classic mistake and it''ll run terribly or not at all. Match the arrow to the old filter''s orientation."}]}, {"n": 5, "title": "Prime and check", "blocks": [{"t": "text", "b": "Battery back on, fuse #18 back in. Turn the key to run (don''t crank) a few times to let the pump prime and pressurize, checking the connections for weeping each time. Then start it, and check again for leaks before you drop the car. Cover back on."}]}], "alsoReplace": [{"name": "Fuel filter hoses / clamps", "why": "Old rubber under the car cracks; if a hose is hard or a clamp is rusty, replace it while it''s off."}, {"name": "Air filter & oil", "why": "If you''re doing the used-car once-over, these are the companion items."}], "check": {"tab": "Is it fuel?", "title": "Is the filter your problem?", "illId": "e36-fuelfilter", "illCap": "Fuel-starvation symptoms overlap with ignition — rule out the cheap stuff first.", "rows": [{"see": "Sputter under load, hard hot starts, unknown history", "means": "A clogged filter is a strong, cheap first suspect.", "do": "Replace it. It''s a maintenance item regardless."}, {"see": "Rough idle at a standstill, no load stumble", "means": "More likely a vacuum leak, ICV or coils.", "do": "See the intake boot / ICV and plugs & coils guides first."}, {"see": "Whining pump, no start", "means": "Could be the in-tank pump, not the filter.", "do": "Check pressure; a new filter won''t fix a dead pump."}], "c": {"level": "community", "n": 3, "note": "Standard fuel-delivery diagnosis."}}, "aftercare": ["Note the mileage.", "Re-check the connections after the first drive."], "disagreements": [{"topic": "Which fuse?", "pos": "Bentley says #18 but its diagram can point wrong.", "call": "Verify with the label on the fuse-box lid before pulling."}, {"topic": "Interval", "pos": "30k vs 40k vs ''every Inspection II''.", "call": "30–40k, or now if unknown."}], "sources": ["Pelican Parts E30/E36 fuel filter replacement", "Bimmerdiy E36/S52 fuel filter change (fuse #18)", "Red Eye Garage E36 M3 fuel filter write-up", "Doug''s Domain E36 fuel filter DIY (interval)", "BimmerWorld / Turner filter fitment (13321740985)"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-belts', '{"id": "e36-belts", "title": "Drive belts & tensioners", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US)", "alsoFits": "Same belt layout across M50/M52/S52: E36 328i · E39 528i · Z3 2.8 & M", "category": "Engine", "kind": "repair", "heroId": "e36-belts", "glance": {"timeFirst": "1 hr", "timeRepeat": "30 min", "difficulty": 2, "cost": "$40–120 (belts + tensioner + pulley)", "risk": "Working near the fan · a thrown belt strands you", "why": "Two belts drive everything: the main V-ribbed belt runs the alternator, water pump and power steering, and a smaller belt runs the A/C. They dry-rot and crack with age, and the plastic tensioner pulleys go brittle and squeal. A cracked belt or a failed pulley leaves you stranded with no charging and no water pump — cheap to prevent.", "note": "Easiest from underneath: drop the belly pan and you skip removing the fan, shroud and coolant tank. Photograph the routing before anything comes off."}, "heroCap": "The A/C belt is outermost; the main V-ribbed belt runs behind it. Each has its own tensioner — the A/C tensioner takes an 8 mm hex, the main hydraulic tensioner a 16 mm socket. The adjusting and idler pulleys are the usual squeal source.", "lifespan": {"title": "When to expect it", "headline": ["Belts every 60,000 miles or whenever cracked; pulleys/tensioner when they squeal or feel rough"], "earliest": "Sooner on a car that''s sat — rubber dry-rots with age, not just miles", "detail": "Flip the belt and look at the ribs: cracks across them mean it''s dry-rotted and about to shed. A squeal on start-up or a rough, noisy pulley when you spin it by hand is the tensioner or an idler on its way out. The pulleys are plastic/rubber and get brittle from engine-bay heat.", "factors": ["Age and heat", "A car that''s been parked", "An original tensioner never replaced"], "inspect": ["Yearly: flip the belt for rib cracks, spin the pulleys for roughness or noise."], "confidence": {"level": "community", "n": 4, "note": "Owner practice and vendor notes; a standard wear set."}}, "should": {"yesIf": ["Cracks across the belt ribs", "Squeal on cold start or under electrical load", "A pulley that''s rough or noisy spun by hand", "You''re already in here for the water pump or alternator"], "codes": [], "notes": ["Do the belt, the tensioner and the idler/adjusting pulley together — they wear as a set and it''s the same access. Kits bundle all three.", "There are two tensioner styles across the E36 run (spring vs hydraulic). The M3 uses the hydraulic type on the main belt (16 mm); check yours before ordering a tensioner."], "confidence": {"level": "high", "n": 4, "note": "Procedure and the do-it-as-a-set advice agree across Turner, Pelican and the e39source/ECS guides."}}, "parts": [{"tier": "oe", "name": "Main V-ribbed belt (alt / water pump / PS)", "pn": "6-rib, ~2080 mm (Conti / Gates / BMW)", "note": "Behind the A/C belt", "price": "$15–30", "links": []}, {"tier": "oe", "name": "A/C belt", "pn": "BMW 11281437449 (5PK906)", "note": "Outermost belt", "price": "$12–20", "links": []}, {"tier": "oe", "name": "Main belt tensioner (hydraulic)", "pn": "per your tensioner type", "note": "Replace with the belt if original", "price": "$40–70", "links": []}, {"tier": "oe", "name": "Adjusting / idler pulley (INA)", "pn": "—", "note": "The primary squeal source; rubber cracks", "price": "$20–40", "links": []}], "aftermarket": [{"name": "ECS accessory belt kit (Kevlar belt + A/C belt + tensioner + idler)", "note": "Everything as a set in one box; the red Kevlar belt is a cosmetic-plus-durability option. The easy way to do it all at once.", "price": "$90–140", "signal": "One-box pick", "links": []}], "tools": [{"name": "8 mm hex for the A/C tensioner"}, {"name": "16 mm socket + ratchet for the main hydraulic tensioner", "note": "a belt-tool set covers both"}, {"name": "T20/T25 or screwdriver for the belly pan (9 screws)"}, {"name": "New belts and pulleys; a phone photo of the routing"}], "before": ["Photograph the belt routing, or find the routing diagram, before anything comes off.", "Work from below: front belly pan off (about nine screws) and both belts are in reach without touching the fan or coolant tank.", "Engine cold."], "steps": [{"n": 1, "title": "Belly pan off", "blocks": [{"t": "text", "b": "Lift the front, remove the plastic belly pan (roughly nine screws). You''re now looking up at the crank pulley and the belt system."}]}, {"n": 2, "title": "A/C belt off", "blocks": [{"t": "text", "b": "Swing the A/C tensioner with an 8 mm hex to release tension, slip the outer A/C belt off, and let the tensioner return."}, {"t": "ill", "id": "e36-belts", "cap": "A/C belt outermost (8 mm tensioner), main belt behind it (16 mm tensioner). Idler/adjusting pulley is the squeal source."}]}, {"n": 3, "title": "Main belt off", "blocks": [{"t": "text", "b": "Rotate the main hydraulic tensioner with a 16 mm socket to take the load off, slide the V-ribbed belt off the pulleys, and ease the tensioner back."}]}, {"n": 4, "title": "Inspect and replace pulleys / tensioner", "blocks": [{"t": "text", "b": "With the belts off, spin every pulley by hand: any roughness, wobble or noise means replace it. Swap the tensioner and the idler/adjusting pulley now if they''re original — it''s the same access and they''re the usual failure."}]}, {"n": 5, "title": "Route the new belts", "blocks": [{"t": "text", "b": "Fit the main V-ribbed belt first, following your photo/diagram, seating it fully in every pulley groove. Hold the tensioner off while you loop the last pulley, then let it take up tension. Then the A/C belt the same way."}, {"t": "warn", "b": "A belt that''s one rib off on a pulley, or riding a flat idler crooked, will shred in minutes. Check every pulley seats the ribs squarely before you start it."}]}, {"n": 6, "title": "Spin, start, check", "blocks": [{"t": "text", "b": "Rotate the engine by hand a couple of turns (socket on the crank) and confirm both belts track true. Belly pan on, start it, and watch that the belts run centred with no squeal or edge-fray."}]}], "alsoReplace": [{"name": "Water pump & thermostat", "why": "The belt''s off and the pump is right there — if the cooling system is due, do it together. See the cooling guide."}, {"name": "Tensioner & idler pulley", "why": "Same access, wear as a set with the belt. Kits include them."}], "check": {"tab": "Belt or pulley?", "title": "Belt, tensioner, or idler?", "illId": "e36-belts", "illCap": "Cracks say belt; noise and roughness say pulley or tensioner.", "rows": [{"see": "Cracks across the ribs", "means": "Belt is dry-rotted.", "do": "Replace the belt; check pulleys while you''re there."}, {"see": "Squeal on cold start, rough pulley by hand", "means": "Idler/adjusting pulley or a weak tensioner.", "do": "Replace the pulley and/or tensioner with the belt."}, {"see": "Chirp under electrical load only", "means": "Belt slipping — glazed belt or weak tensioner.", "do": "New belt and tensioner."}], "c": {"level": "community", "n": 3, "note": "Standard belt-system diagnosis."}}, "aftercare": ["Re-check tracking after the first drive.", "A new squeal usually means a belt not fully seated or a pulley missed."], "disagreements": [{"topic": "From above or below?", "pos": "Top needs fan/shroud/coolant tank off; below needs only the belly pan.", "call": "From below — far less to remove."}, {"topic": "Which tensioner?", "pos": "Spring vs hydraulic across the E36 run.", "call": "M3 main belt is hydraulic (16 mm); confirm before ordering."}], "sources": ["Turner Motorsport E36 drive belts & tensioners (fitment, pulley failure notes)", "Pelican Parts E30/E36 belt replacement", "e39source M52 serpentine belt DIY (belt sizes, tensioner tools, top-vs-below)", "ECS accessory belt kit / routing references", "AUTODOC E36 serpentine belt sequence"], "embeds": []}'::jsonb);
insert into guides (id, content) values ('e36-intake-boot-icv', '{"id": "e36-intake-boot-icv", "title": "Intake boot, ICV & vacuum leaks", "fits": "1996–1999 BMW M3 · 3.2 S52 (S52B32US, single throttle body)", "alsoFits": "Same single-throttle-body intake as M50/M52/M54 sixes (E36 328i, E39 528i, Z3). Note: Euro S50 M3 has six throttle bodies and differs.", "category": "Engine", "kind": "repair", "heroId": "e36-intake-idle", "glance": {"timeFirst": "1–2 hr", "timeRepeat": "30 min", "difficulty": 2, "cost": "$0 (cleaning) – $250 (boot + ICV + CCV)", "risk": "Cheap parts, no real hazard", "why": "A rough, hunting or hanging idle on an S52 is almost always air getting in where it shouldn''t. The cracked intake boot is so common it''s practically a service item; add a gummed-up idle control valve, a tired crankcase vent, and hardened vacuum lines, and you''ve named the usual suspects. This guide works the cheap fixes first before you''re pulling the manifold.", "note": "US S52 has one throttle body and one ICV — the conventional job. The Euro S50 M3 with individual throttle bodies is a different animal."}, "heroCap": "Air enters through the boot between the airbox/HFM and the throttle body — this rubber cracks near its ribs. The idle control valve meters idle air; the crankcase vent (CCV) and the vacuum lines under the manifold are the other leak paths.", "lifespan": {"title": "When to chase it", "headline": ["Any rough, surging, hunting or hanging idle, or a lean-mixture code"], "earliest": null, "detail": "The intake boot cracks on nearly every high-mileage E36 — oil fumes in the bay weaken the rubber, and the split hides near the moulded ribs. A dirty ICV sticks and gives a bouncing or bogging idle, worst with the A/C or headlights on. A cracked CCV diaphragm adds a vacuum leak plus oil into the intake (blue smoke, worst-case hydrolock).", "factors": ["Age (boot rubber)", "Never-cleaned ICV", "A CCV that''s gone gummy", "Hardened vacuum lines under the manifold"], "inspect": ["Rough idle: eyeball the boot for splits and pull the oil cap to feel for CCV vacuum before buying parts."], "confidence": {"level": "community", "n": 4, "note": "Owner consensus that the boot and ICV are the usual E36 rough-idle causes."}}, "should": {"yesIf": ["Rough, surging or hunting idle", "Idle bogs or bounces with A/C or headlights on", "Lean-mixture or misfire codes with no obvious cause", "A whistle or hiss at idle that changes when you pinch a vacuum line"], "codes": ["P0171", "P0174", "P1188", "P1189"], "notes": ["Work cheapest-first: inspect the boot, clean the HFM (air-mass meter), clean the ICV — that fixes most rough idles for the price of a can of cleaner. Only then move to the CCV and the vacuum lines under the manifold.", "If you''re pulling the throttle body to reach the CCV, replace the vacuum lines and the ICV hose under there while it''s exposed — they''re almost always cracked and you won''t want to go back in."], "confidence": {"level": "high", "n": 4, "note": "Diagnostic order agrees across ShiftBMW, Doug''s Domain and multiple E36 rough-idle write-ups."}}, "parts": [{"tier": "oe", "name": "Intake boot (airbox/HFM to throttle body)", "pn": "per your car", "note": "Cracks near the ribs; the #1 vacuum leak", "price": "$25–60", "links": []}, {"tier": "oe", "name": "Idle control valve (ICV)", "pn": "Bosch 0280140545", "note": "Clean first; replace if cleaning doesn''t cure the sticking", "price": "$150–250", "links": []}, {"tier": "oe", "name": "Crankcase vent (CCV) & hoses", "pn": "—", "note": "Oil separator; cracked diaphragm = vacuum leak + oil in intake", "price": "$30–90", "links": []}, {"tier": "oe", "name": "Vacuum lines / ICV hose", "pn": "—", "note": "The hoses under the manifold are almost always cracked by now", "price": "$10–30", "links": []}, {"tier": "oe", "name": "MAF/HFM cleaner, throttle-body cleaner", "pn": "—", "note": "For the ICV, throttle body and air-mass sensor", "price": "$12", "links": []}], "aftermarket": [], "tools": [{"name": "Screwdrivers and pliers for hose clamps; T30 Torx for the ICV bracket"}, {"name": "10/11 mm for the throttle body if you go that far", "note": "only needed to reach the CCV"}, {"name": "HFM/MAF cleaner and throttle-body cleaner, rags, a flashlight"}], "before": ["Battery off if you''ll unplug the ICV or HFM, to avoid stored faults.", "Have a can of MAF-safe cleaner and throttle-body cleaner ready.", "Work in order — cheap and easy first. Don''t pull the manifold until the simple stuff is ruled out."], "steps": [{"n": 1, "title": "Inspect the intake boot", "blocks": [{"t": "text", "b": "Trace the rubber boot from the airbox/HFM to the throttle body. Flex it and look closely at the moulded ribs — the cracks hide there and can be hairline. A split anywhere here is unmetered air and a rough idle. Replace the boot if it''s cracked; this alone fixes a huge share of E36 idle complaints."}, {"t": "ill", "id": "e36-intake-idle", "cap": "Boot (cracks at the ribs) → throttle body → ICV. CCV and the under-manifold vacuum lines are the deeper leak paths."}]}, {"n": 2, "title": "Clean the air-mass sensor (HFM)", "blocks": [{"t": "text", "b": "Unplug and remove the HFM from the intake, spray the sensor element with MAF-safe cleaner (never touch it), let it dry, and clean the connector contacts. A dirty or flaky HFM causes the same rough idle and doesn''t always throw a code."}]}, {"n": 3, "title": "Clean or replace the ICV", "blocks": [{"t": "text", "b": "On the six you can reach the idle control valve without pulling the manifold — snake your arm under the intake, unclip its connector (the clip can be brittle; don''t break it), pull the ICV from under its bracket, and pop its hoses. Spray the inside with throttle-body/carb cleaner, work the flap free, wipe it out, and refit. If it''s still sticking after cleaning, replace it."}, {"t": "note", "b": "The little clip that holds the ICV connector is known to pop out or break — some owners epoxy it back. Handle it gently."}]}, {"n": 4, "title": "Hunt the remaining vacuum leaks", "blocks": [{"t": "text", "b": "With the engine idling, listen for a hiss and check the usual paths: the brake-booster hose, the check valve, the CCV and its lines, and the vacuum lines under the intake manifold. Pinching or briefly blocking a suspect line and watching the idle change tells you when you''ve found it."}]}, {"n": 5, "title": "CCV and under-manifold lines (if needed)", "caution": true, "blocks": [{"t": "text", "b": "If the CCV diaphragm has failed (oil in the intake, blue smoke, a persistent lean/vacuum code), replacing it means pulling the throttle body to reach it. While it''s exposed, replace every vacuum line and the ICV hose under there — they''re the same age and almost all cracked."}, {"t": "warn", "b": "A failed CCV can pull enough oil into the intake to hydrolock the engine in the worst case. Don''t ignore heavy blue smoke plus a vacuum-leak code."}]}, {"n": 6, "title": "Reassemble and verify", "blocks": [{"t": "text", "b": "Everything reconnected, boot clamps snug but not crushing, HFM and ICV plugged in. Battery on, start it, and let it idle to relearn — it should settle smooth within a minute or two. Clear codes and confirm they stay away."}]}], "alsoReplace": [{"name": "PCV / crankcase vent hoses", "why": "If you''re under the manifold, do all the vacuum lines — they''re all the same age."}, {"name": "Valve cover gasket", "why": "Oil fumes are what rot the intake boot; a leaking cover feeds the problem. See that guide."}, {"name": "Coolant temp sensor", "why": "On the manifold, accessible with the throttle body off, and a cheap cause of cold-idle trouble if you''re in there."}], "check": {"tab": "What kind of rough?", "title": "Where''s the rough idle coming from?", "illId": "e36-intake-idle", "illCap": "Match the symptom to the likely leak before you spend.", "rows": [{"see": "Surging/hunting idle, lean code", "means": "Unmetered air — most often the cracked intake boot.", "do": "Inspect and replace the boot first; clean the HFM."}, {"see": "Bogging or bouncing idle, worse with A/C/lights", "means": "Dirty, sticking ICV.", "do": "Clean the ICV; replace if cleaning doesn''t hold."}, {"see": "Rough idle + blue smoke + oil in intake", "means": "Failed CCV diaphragm.", "do": "Replace the CCV and the under-manifold vacuum lines."}, {"see": "Misfire, not really an air issue", "means": "Ignition, not vacuum.", "do": "Plugs & coils first."}], "c": {"level": "community", "n": 3, "note": "Standard E36 rough-idle diagnostic ladder."}}, "aftercare": ["Let the idle relearn after clearing codes.", "If a lean code returns, smoke-test the intake to find the last small leak."], "disagreements": [{"topic": "Clean or replace the ICV?", "pos": "Cleaning fixes many; some stick again.", "call": "Clean first — it''s free-ish. Replace only if it won''t stay smooth."}, {"topic": "Is the CCV worth doing preemptively?", "pos": "$30–90 part, manifold-off labor.", "call": "Do it when you''re already under there or when it''s clearly failed — not on its own for a minor idle."}], "sources": ["ShiftBMW E36 ICV cleaning DIY", "Doug''s Domain E36 ICV & crankcase vent (CCV) DIY", "A Better BMW E36 ICV and CCV write-ups (boot cracks, vacuum-leak sources)", "BMW E36 blog ICV cleaning DIY", "Forum rough-idle threads (boot, ICV, HFM, CCV)"], "embeds": []}'::jsonb);
